theorem five_cover {c : List (Opt (List Nat))} (hc : IsChoice c (groupsEP 5)) {L0 : List Nat}
    (hL0 : L0 ∈ orders 5) (ha : allows c L0 = true) :
    ∃ ρ, ρ ∈ orders 5 ∧ ∃ k, k < 1160 ∧ ∀ L, L ∈ orders 5 → allows c L = memM (rep5T.find k) (rlab ρ L)

theorem psi_inj (hD : IsMaximal D) {σ₁ σ₂ : Order (Fin (n + 1))} {b₁ b₂ : Fin (n + 1)}
    (h₁ : FreePair D σ₁ b₁ (upN σ₁ b₁) (dnN σ₁ b₁)) (h₂ : FreePair D σ₂ b₂ (upN σ₂ b₂) (dnN σ₂ b₂))
    (heq : psi D (b₁, σ₁) = psi D (b₂, σ₂)) : b₁ = b₂ ∧ σ₁ = σ₂

theorem IsExtremeFull.insertionWord_interval {n : Nat} {D : Domain (Fin (n + 1))}
    (hD : IsExtremeFull D) (x : Fin (n + 1)) (P : Order (Fin n)) :
    SlotWord.Interval (insertionWord (optionDomain x D) P)

theorem maximum_peakPit_isExtremeFull {n : Nat} {D : Domain (Fin n)}
    (hD : IsPeakPit D) (hcard : D.card = h n) :
    ∃ L : ExtremeSelection n, D = fullDomain L.val

theorem IsFull.sum_components_deletionSum {n : Nat} {D : Domain (Fin (n+1))}
    (hD : IsFull D) :
    ∑ K ∈ components D, deletionSum K = deletionSum D + gapCount D
